<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'&&has_role('Student')){try{$q=db()->prepare('SELECT id FROM students WHERE user_id=?');$q->execute([actor_id()]);$sid=(int)$q->fetchColumn();$resume=null;$s=db()->prepare('SELECT id FROM job_applications WHERE job_id=? AND student_id=?');$s->execute([(int)$_POST['job_id'],$sid]);if(!$s->fetch()){db()->prepare('INSERT INTO job_applications(job_id,student_id,status) VALUES(?,?,\'Applied\')')->execute([(int)$_POST['job_id'],$sid]);$_SESSION['flash']=['success','Job application submitted'];}}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('jobs.php');}$jobs=db()->query("SELECT j.*,c.name company FROM jobs j JOIN companies c ON c.id=j.company_id WHERE j.status='Open' ORDER BY j.deadline")->fetchAll();page_top('Job Marketplace');flash();?><div class='row g-3'><?php foreach($jobs as $j):?><div class='col-md-6'><div class='card p-4 h-100'><span class='pill'>OPEN ROLE</span><h5 class='mt-2'><?=e($j['title'])?></h5><div><?=e($j['company'])?> · <?=e($j['location'])?></div><div class='text-muted'>Package ₹<?=e(number_format($j['package_amount']))?> · Deadline <?=e($j['deadline'])?></div><p class='mt-3'><?=e($j['eligibility'])?></p><?php if(has_role('Student')):?><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='job_id' value='<?=e($j['id'])?>'><button class='btn btn-primary'>Apply</button></form><?php endif;?></div></div><?php endforeach;?></div><?php page_bottom();
